WHERE is_deleted = 0

    AND model LIKE concat('%', #{param.model}, '%')


    AND api_key_name LIKE concat('%', #{param.apiKeyName}, '%')


    AND platform = #{param.platform}


    AND usage_source = #{param.usageSource}


    AND create_time >= #{param.startTime}


    AND create_time <= #{param.endTime}
